function bothBusy(a: number[][], b: number[][]): number[][] {
  const out: number[][] = [];
  for (const [s1, e1] of a)
    for (const [s2, e2] of b) {
      const lo = Math.max(s1, s2), hi = Math.min(e1, e2);
      if (lo <= hi) out.push([lo, hi]);
    }
  return out.sort((x, y) => x[0] - y[0]);
}

